// Minimal, dependency-free analytics.
// Sends best-effort UI events to the backend; analytics never blocks navigation.
//
// Usage:
//   import { trackEvent, trackPageView } from "@/lib/analytics";
//   trackPageView("landing");
//   trackEvent("cta_click", { id: "hero-primary" });

const SESSION_KEY = "ayana_session_id";
const SOURCE_KEY = "ayana_acquisition_source";
const GUIDE_KEY = "ayana_guide_viewed";
const API_BASE = process.env.REACT_APP_BACKEND_URL || "";

export function getSessionId() {
  try {
    let id = sessionStorage.getItem(SESSION_KEY);
    if (!id) {
      id = `s_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
      sessionStorage.setItem(SESSION_KEY, id);
    }
    return id;
  } catch {
    return "no-session";
  }
}

export function getGuideSessionId() {
  try {
    if (sessionStorage.getItem(GUIDE_KEY) !== '1') return null;
    const id = getSessionId();
    return id === 'no-session' ? null : id;
  } catch {
    return null;
  }
}

export function withGuideAttribution(payload) {
  const session = getGuideSessionId();
  return session ? { ...payload, analytics_session_id: session } : payload;
}

function send(payload) {
  const body = JSON.stringify({
    ...payload,
    session_id: getSessionId(),
    path: typeof window !== "undefined" ? window.location.pathname : "",
    lang: typeof document !== "undefined" ? document.documentElement.getAttribute("data-lang") : null,
    ts: new Date().toISOString(),
  });

  // Keep a bounded local trail before dispatch; a failed send does not imply server receipt.
  try {
    const key = "ayana_local_events";
    const existing = JSON.parse(localStorage.getItem(key) || "[]");
    existing.push(JSON.parse(body));
    localStorage.setItem(key, JSON.stringify(existing.slice(-200))); // cap growth
  } catch {
    // ignore
  }

  try {
    // Prefer sendBeacon — doesn't block navigation, fires even on page unload
    if (navigator?.sendBeacon && API_BASE) {
      const blob = new Blob([body], { type: "application/json" });
      navigator.sendBeacon(`${API_BASE}/api/analytics/event`, blob);
      return;
    }
    if (API_BASE) {
      fetch(`${API_BASE}/api/analytics/event`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body,
        keepalive: true,
      }).catch(() => {});
    }
  } catch {
    // Analytics must never break the app. Swallow and move on.
  }
}

export function trackPageView(page) {
  let source = 'direct_or_unknown';
  try {
    const stored = sessionStorage.getItem(SOURCE_KEY);
    const tagged = new URLSearchParams(window.location.search).get('utm_source')?.toLowerCase();
    const host = document.referrer ? new URL(document.referrer).hostname : '';
    const known = ['linkedin', 'reddit', 'instagram', 'youtube'];
    source = (stored && [...known, 'chatgpt', 'other'].includes(stored) ? stored : null)
      || (tagged ? (tagged === 'chatgpt.com' || tagged === 'chatgpt' ? 'chatgpt' : known.includes(tagged) ? tagged : 'other')
      : (host === 'chatgpt.com' || host.endsWith('.chatgpt.com') ? 'chatgpt'
        : known.find(s => host === `${s}.com` || host.endsWith(`.${s}.com`)))) || source;
    if (!stored && source !== 'direct_or_unknown') sessionStorage.setItem(SOURCE_KEY, source);
  } catch { /* No raw referrer or query string is stored. */ }
  if (page === 'guide') {
    try { sessionStorage.setItem(GUIDE_KEY, '1'); } catch { /* Tracking remains best effort. */ }
  }
  send({ type: "page_view", page, meta: { source } });
}

export function trackEvent(name, meta = {}) {
  send({ type: "event", name, meta });
}
